+    fn hash_at_indexes<const N: usize>(&self, hash_indexes: [u64; N]) -> [u64; N] {
+        // FNV-1a with several keys at once, matching `FnvHasher::with_key`.
+        let mut hashes = hash_indexes;
+        for &byte in self.as_ref() {
+            for hash in &mut hashes {
+                *hash ^= u64::from(byte);
+                *hash = hash.wrapping_mul(0x100000001b3);
+            }
+        }
+        hashes
+    }
+}

